def breadcrumbs(path):
    if path=='/': return ''
    segments=[s for s in path.strip('/').split('/') if s]
    items=[('Home','/')]
    agg=''
    titles={'chi-sono':'Chi sono','la-mia-storia':'La mia storia','metodo-commerciale':'Il metodo','risultati':'Risultati','progetti':'Progetti','direttore-commerciale':'Direttore commerciale','formazione-venditori':'Formazione venditori','approfondimenti':'Approfondimenti','kpi-commerciali':'KPI commerciali','recupero-lead-crm':'Recupero lead CRM','come-scalare-team-sales':'Scalare un team sales','contatti':'Contatti','privacy':'Privacy','alan-collura-inglese-per-negati':'Alan Collura e Inglese per Negati'}
    for s in segments:
        agg+=s+'/'
        items.append((titles.get(s,s.replace('-',' ').title()), '/'+agg))
    parts=['<nav class="crumbs" aria-label="Percorso di navigazione">']
    for i,(name,url) in enumerate(items):
        if i: parts.append('<span aria-hidden="true">/</span>')
        if i==len(items)-1: parts.append('<span aria-current="page">'+escape(name)+'</span>')
        else: parts.append('<a href="'+url+'">'+escape(name)+'</a>')
    parts.append('</nav>')
    return ''.join(parts)

def ld_graph(path,page):
    canonical=DOMAIN+path
    graph=[
    {'@type':'Person','@id':PERSON_ID,'name':'Alan Collura','url':DOMAIN+'/','jobTitle':'Direttore commerciale e Sales Manager','alternateName':['Collura Alan'],'description':'Alan Collura è un professionista della direzione commerciale e della formazione sales, fondatore di Recupero Fatturato e MetodoVendita e già impegnato nella crescita commerciale di Inglese per Negati.','knowsAbout':['Direzione commerciale','Sales management','Formazione venditori','Sales operations','KPI commerciali','Gestione CRM','Strategia di vendita'],'subjectOf':[{'@type':'WebPage','url':'https://recuperofatturato.com/'},{'@type':'WebPage','url':DOMAIN+'/alan-collura-inglese-per-negati/'}]},
    {'@type':'WebSite','@id':SITE_ID,'name':'Alan Collura','alternateName':['alancollura.com'],'url':DOMAIN+'/','inLanguage':'it-IT','publisher':{'@id':PERSON_ID}},
    {'@type':'WebPage' if not page.get('article') else 'Article', '@id':canonical+'#webpage','url':canonical,'name':page['title'],'description':page['description'],'inLanguage':'it-IT','isPartOf':{'@id':SITE_ID},'about':{'@id':PERSON_ID}}
    ]
    if path=='/':graph[-1]['@type']='WebPage';graph[-1]['mainEntity']={'@id':PERSON_ID}
    if path=='/chi-sono/':graph[-1]['@type']='ProfilePage';graph[-1]['mainEntity']={'@id':PERSON_ID}
    if page.get('article'):
        graph[-1].update({'@type':'BlogPosting','headline':page['headline'].replace('<em>','').replace('</em>',''),'author':{'@id':PERSON_ID},'datePublished':'2026-10-31','dateModified':'2026-10-31','mainEntityOfPage':canonical,'image':DOMAIN+'/assets/og-alan-collura.png'})
    if path!='/':
        seg=[s for s in path.strip('/').split('/') if s]
        crumbs=[{'@type':'ListItem','position':1,'name':'Home','item':DOMAIN+'/'}]
        accum=''
        for i,s in enumerate(seg,2):
            accum+=s+'/'
            crumbs.append({'@type':'ListItem','position':i,'name':{'chi-sono':'Chi sono','la-mia-storia':'La mia storia','metodo-commerciale':'Metodo commerciale','risultati':'Risultati','progetti':'Progetti','direttore-commerciale':'Direttore commerciale','formazione-venditori':'Formazione venditori','approfondimenti':'Approfondimenti','kpi-commerciali':'KPI commerciali','recupero-lead-crm':'Recupero lead CRM','come-scalare-team-sales':'Scalare un team sales','contatti':'Contatti','privacy':'Privacy','alan-collura-inglese-per-negati':'Alan Collura e Inglese per Negati'}.get(s,s.replace('-',' ').title()),'item':DOMAIN+'/'+accum})
        graph.append({'@type':'BreadcrumbList','itemListElement':crumbs})
    if page.get('faq'):
        graph.append({'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in page['faq']]})
    return {'@context':'https://schema.org','@graph':graph}

def page_html(path,page):
    canonical=DOMAIN+path
    current=path.strip('/').split('/')[0]
    linktags=''.join(f'<a href="{url}" '+('aria-current="page"' if url.strip('/')==current else '')+f'>{name}</a>' for name,url in nav)
    if page.get('home'):main=page['body']
    else:
        main=f'''<section class="subhero"><div class="subhero-lines" aria-hidden="true"></div><div class="container subhero-inner">{breadcrumbs(path)}<div class="eyebrow eyebrow-light"><span class="eyebrow-dot"></span> {page['eyebrow']}</div><h1>{page['headline']}</h1><p>{page['lead']}</p></div><span class="subhero-index" aria-hidden="true">AC / {path.strip('/').split('/')[-1].replace('-',' ').upper()}</span></section>'''+page['body']
